  function acceptPin(auth,commit=false){if(!auth)return false;if(pin&&(auth.seq<pin.seq||auth.seq===pin.seq&&auth.chainId!==pin.chainId||auth.seq>pin.seq&&pin.seq>0&&!auth.prefixIds.includes(pin.chainId)))return false;if(commit&&(!pin||auth.seq>pin.seq)){if(!write('blackjack.authority.'+code,auth))return false;pin=auth;}return true;}
  async function ensureGuest(){const k='blackjack.identity.'+code;if(!identity)identity=read(k,session)||await C.identity();if(!write(k,identity,session))throw Error('无法保存身份，请允许会话存储');const ek='blackjack.exchange.'+code;exchange=read(ek,session)||await C.exchangeIdentity();if(!write(ek,exchange,session))throw Error('无法保存交接身份');}
  async function sendGuestTransfer(type,fields){await publish({type:'guest',pub:identity.pub,keyCode:identity.code,...await C.sign({kind:'bj-guest-v2',room:code,peer:identity.code,type,sync,proof,...fields},identity.privateKey)});}
