  async function transferPacket(kind,data){return{type:'dealer-transfer',pub:owner.pub,chain:owner.chain||[],...await C.sign({kind,room:code,...data},owner.privateKey)};}
  const encodePacked=bytes=>{let out='';for(let i=0;i<bytes.length;i+=16384)out+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(out).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
