  async function stageHandoff(p){try{
   if(!handoff||handoff.rev!==rev||!handoffWindow())return;handoff.phase='staging';if(game.round>0&&!owner.roundDealerName)owner.roundDealerName=name;save();const payload=clone(owner);delete payload.privateKey;delete payload.token;payload.seats=clone(seats);payload.actorAliases={...(owner.actorAliases||{}),[identity.code]:owner.actorPeer||code};
   for(const id of IDS)if(payload.seats[id]?.ownerId===handoff.peer){payload.seats[id]={ownerId:identity.code,pub:identity.pub,name};payload.seatScores[id]=0;}
   if(payload.tableSession){payload.tableSession.confirmed={};for(const [id,r]of Object.entries(payload.tableSession.reservations||{}))if(r.ownerId===handoff.peer)delete payload.tableSession.reservations[id];}payload.actorPeer=actor(handoff.peer);payload.keyCode=handoff.peer;payload.pub=p.pub;payload.rev=rev+1;payload.lastAt=Math.max(lastAt,wall());payload.expires=wall()+86400000;
   handoff.payload=payload;handoff.cert=await C.authorizeHost(owner,{pub:p.pub,keyCode:handoff.peer},{transferId:handoff.id,seq:(owner.chain||[]).length+1,actorPeer:payload.actorPeer,at:Math.max(1,wall())});
   const sealed=await C.sealFor(await packHandoff(payload,p.gzip===true),p.exchangePub,transferContext(handoff.id,handoff.peer));handoff.packet=await transferPacket('bj-handoff-stage',{id:handoff.id,target:handoff.peer,rev,sealed});const preview=await cipher.seal(handoff.packet);if(preview.length>=240000)throw Error('安全交接消息超过传输大小上限，原房主仍然有效。');await publish(handoff.packet);emit();
  }catch(e){handoff=null;owner.handoffError=e.message||'安全交接打包失败，原房主仍然有效。';await broadcast();emit(owner.handoffError);}}

  async function commitHandoff(){
   const h=handoff;if(!h||!handoffWindow()||h.rev!==rev)return;const packet=await transferPacket('bj-handoff-commit',{id:h.id,target:h.peer,rev:rev+1,cert:h.cert});
   const marker={code,transferred:true,commit:packet,expires:wall()+86400000};if(!write(ownerKey(),marker)){emit('保存失败，交接尚未生效。');return;}commitRetry=packet;await publish(packet);directory?.close();directory=null;role='watch';owner=null;handoff=null;seats=h.payload.seats;publicMeta={...emptyMeta(),...h.payload};publicGame=T.publicState(game,{historyLimit:0});rev++;ready=false;lastSeen=-Infinity;pin=await C.authority({pub:h.payload.pub,chain:[...(packet.chain||[]),h.cert]},code);write('blackjack.authority.'+code,pin);resetSync();setUrl('watch');await hello();emit('交接已确认，正在同步新庄家。');
  }
  async function receiveTransfer(packet){
   const auth=await C.authority(packet,code);if(!acceptPin(auth))return;const d=await C.verify(packet,packet.pub,code);if(!d||d.room!==code||typeof d.id!=='string')return;
   if(d.kind==='bj-handoff-stage'){
    if(role==='host'||d.target!==identity?.code||!incoming||incoming.id!==d.id||consented!==d.id||!handoffWindow()||d.rev!==rev)return;
    let payload;try{payload=await unpackHandoff(await C.openFor(d.sealed,exchange.privateKey,transferContext(d.id,d.target)));T.Engine.restore(payload.saved);}catch(e){emit(e.message||'安全交接资料无法读取，原房主仍然有效。');return;}
    if(payload.pub!==identity.pub||payload.code!==code||payload.keyCode!==identity.code||payload.privateKey||payload.token||IDS.some(id=>payload.seats?.[id]?.ownerId===identity.code))return;
    const record={id:d.id,payload,fromPub:packet.pub,chain:packet.chain||[]};if(!write('blackjack.staged.'+code,record)){emit('本地保存失败，无法接任；原庄家仍有效。');return;}staged=record;await sendGuestTransfer('dealer-ack',{transferId:d.id});emit('已安全保存，等待原庄家确认交接。');return;
   }
   if(d.kind!=='bj-handoff-commit'||d.rev<rev)return;const cd=JSON.parse(d.cert?.data||'{}');if(cd.transferId!==d.id||cd.toKeyCode!==d.target)return;const chain=[...(packet.chain||[]),d.cert],next=await C.authority({pub:cd.toPub,chain},code);if(!next||next.seq!==auth.seq+1||!acceptPin(next))return;
   if(d.target===identity?.code){if(!staged||staged.id!==d.id||staged.fromPub!==packet.pub||staged.payload.rev!==d.rev||JSON.stringify(staged.chain)!==JSON.stringify(packet.chain||[])||staged.payload.expires<=wall())return;const candidate={...staged.payload,chain,privateKey:identity.privateKey};if(!write(ownerKey(),candidate)){emit('接任保存失败，请保留当前页面。');return;}if(!acceptPin(next,true))return;owner=candidate;game=T.Engine.restore(owner.saved);seats=owner.seats;role='host';rev=owner.rev;lastAt=owner.lastAt;epoch=C.nonce();ready=true;incoming=null;staged=null;write('blackjack.staged.'+code,null);commitRetry=null;write(leaseKey(),{id:leaseId,at:wall()});setUrl();claimAlias(generation);await broadcast();emit('你已成为庄家和房主，原牌局与积分均已保留。');
   }else{if(!acceptPin(next,true))return;ready=false;resetSync();await hello();}
  }

  function connect(){const ticket=generation;for(const url of RELAYS){const client=M.connect(url,{clientId:'bj_'+C.id(),...(url.includes('shiftr.io')?{username:'public',password:'public'}:{}),clean:true,connectTimeout:8000,reconnectPeriod:4000,keepalive:25});clients.push(client);
   client.on('connect',()=>{if(ticket!==generation||closed)return;client.subscribe(topic,{qos:0},(error,granted)=>{if(ticket!==generation||closed||error||!client.connected||!Array.isArray(granted)||!granted.some(g=>g.topic===topic&&g.qos<128))return;client.bjReady=true;status='房间已连接。';hello().catch(()=>{});emit();});});
   client.on('message',(_,raw)=>{if(ticket!==generation||closed)return;receiveChain=receiveChain.then(()=>receive(raw.toString())).catch(()=>{});});for(const event of ['close','offline'])client.on(event,()=>{client.bjReady=false;if(ticket===generation)emit();});client.on('error',()=>{});
  }}
  async function claimAlias(ticket){try{const result=await D.claim({...owner,alias},value=>{if(ticket!==generation)return;alias=value;owner.alias=value;save();setUrl();emit();broadcast().catch(()=>{});});if(ticket!==generation)result.close();else directory=result;}catch{if(ticket===generation)emit('房间码暂未生成，可先复制邀请链接；稍后点重新连接。');}}
  function cleanup(){generation++;closed=true;cancel(aiTimer);stop(tickTimer);directory?.close();directory=null;clients.forEach(c=>c.end(true));clients=[];if(role==='host'&&read(leaseKey())?.id===leaseId)write(leaseKey(),null);peers.clear();seen.clear();acks.length=0;actionResults.length=0;pendingAction=null;sendChain=Promise.resolve();receiveChain=Promise.resolve();}
  async function openRoom(roomId,join='player',knownAlias=''){
   if(!validName(name))throw Error('请先填写昵称');cleanup();const ticket=generation;code=C.normalize(roomId);if(!C.valid(code))throw Error('无效房间链接');mode='online';closed=false;lastRecentKey='';joinedAt=mono();alias=/^\d{4}$/.test(knownAlias)?knownAlias:'';owner=null;identity=null;exchange=null;consented=null;ready=false;lastAt=0;lastSeen=-Infinity;rev=0;hostEpoch='';retiredEpochs.clear();privateCards={roundToken:'',faces:{}};proof='';sync='';heartbeat=-Infinity;members=[];seats=emptySeats();publicMeta=emptyMeta();
   const saved=read(ownerKey());pin=read('blackjack.authority.'+code);handoff=null;incoming=null;staged=read('blackjack.staged.'+code);commitRetry=saved?.transferred?saved.commit:null;if(join==='host'&&saved?.code===code&&!saved.transferred&&saved.expires>wall()){
    if(!acceptPin(await C.authority({pub:saved.pub,chain:saved.chain||[]},code),true)||!await C.verify({...await C.sign({check:code},saved.privateKey),chain:saved.chain||[]},saved.pub,code))throw Error('房主存档无效');const lease=read(leaseKey());if(lease&&lease.id!==leaseId&&wall()-lease.at<15000)throw Error('这个房间已在另一个房主页打开，请先关闭重复页面。');
    owner={...emptyMeta(),...saved};game=T.Engine.restore(saved.saved);role='host';if(game.phase==='idle'&&!T.publicState(game,{historyLimit:0}).rules?.classic&&typeof T.upgrade==='function')game=T.upgrade(game,{infinite:true});rev=saved.rev||0;lastAt=saved.lastAt||0;alias=saved.alias||alias;seats={...emptySeats(),...(saved.seats||{})};epoch=C.nonce();ready=true;write(leaseKey(),{id:leaseId,at:wall()});pendingInvite=null;
   }else{role='watch';const key='blackjack.identity.'+code;let stored=read(key,session);try{if(!stored||!await C.verify(await C.sign({check:code},stored.privateKey),stored.pub,stored.code))stored=null;}catch{stored=null;}identity=stored||await C.identity();write(key,identity,session);pendingInvite={room:code,join,alias};publicGame=T.publicState(new T.Engine({chips:true,classic:true,infinite:true}));resetSync();}
   await ensureGuest();if(ticket!==generation)return;cipher=await new C.Cipher(code).init();topic='daydream/blackjack/v2/'+await C.topic(code);connect();tickTimer=repeat(tick,2000);if(role==='host')claimAlias(ticket);setUrl(role==='host'?null:join);emit(role==='host'?'把玩家邀请发给好友；空位允许同一玩家兼玩。':'正在与房主同步，请双方保持页面打开。');
  }
  function tick(){if(mode!=='online'||closed)return;if(commitRetry)publish(commitRetry).catch(()=>{});if(handoff&&mono()-handoff.at>20000){handoff=null;emit('接任超时，原庄家仍负责房间，可重新邀请。');broadcast().catch(()=>{});}if(role==='host'){const lease=read(leaseKey());if(lease&&lease.id!==leaseId&&wall()-lease.at<15000){cleanup();mode='entry';emit('另一个房主页已接管，请关闭重复页面。');return;}write(leaseKey(),{id:leaseId,at:wall()});}if(mono()-heartbeat>4000){heartbeat=mono();hello().catch(()=>{});}if(pendingAction&&mono()-pendingAction.at>10000){pendingAction=null;status='未收到确认，请连接恢复后重试；不会自动重复要牌。';}if(role!=='host'&&ready&&!fresh())status='等待房主恢复连接，当前牌局已暂停。';else if(role!=='host'&&!ready&&mono()-joinedAt>25000)status='尚未收到21点房主同步，请核对游戏和房间码，并让房主保持页面打开。';emit();}
  function startRound(){const ts=tableSession(),ids=IDS.filter(id=>seats[id]);if(!ts||ts.stage!=='betting'||!betsConfirmed())throw Error('请在下注阶段由全部玩家确认正数下注');if(!ids.length)throw Error('请先认领至少一个玩家席');if(!affordable())throw Error('玩家筹码不足，或庄家筹码不足以覆盖本桌赔付');if(game.round>=game.rounds)throw Error('已完成本桌连续局数');if(!T.publicState(game,{historyLimit:0}).rules?.classic&&typeof T.upgrade==='function')game=T.upgrade(game,{infinite:true});meta().roundDealer=mode==='solo'?'house':owner.actorPeer||code;meta().roundDealerName=mode==='solo'?'熊二':name;meta().roundSeats=clone(seats);meta().revealState={round:game.round+1,roundToken:C.nonce(),cards:{},ledgerBefore:clone(game.ledger)};game.startRound(ids,Object.fromEntries(ids.map(id=>[id,stake(id)])));for(const peer of betActors())ts.previousBets[peer]=Object.fromEntries(ids.filter(id=>actor(seats[id].ownerId)===peer).map(id=>[id,stake(id)]));ts.stage='playing';if(chipEnabled()){meta().entryLocked||={};for(const peer of [meta().roundDealer,...ids.map(id=>actor(seats[id].ownerId))])meta().entryLocked[peer]=true;}accountSettlement();}

  async function guestAction(action,seatId,amount){if(mode!=='online'||role==='host'||!online()||!fresh()||!proof||!syncConfirmed||pendingAction)throw Error('请等待房间同步后操作');const id=C.id(),data={kind:'bj-guest-v2',room:code,peer:identity.code,type:'action',id,action,seatId,sessionToken:tableSession()?.stageId,revealRound:rawGame().reveal?.roundToken,...(action==='revealAllCards'?{revealTokens:myRevealTokens()}:{}),betKey:betFingerprint(identity.code),...(amount===undefined?{}:{amount}),rev,sync,proof};pendingAction={id,at:mono()};emit('正在同步你的选择…');await publish({type:'guest',pub:identity.pub,keyCode:identity.code,...await C.sign(data,identity.privateKey)});return true;}
  async function mutate(action,requestedSeat,amount){const id=requestedSeat||activeHand();if(revealPending())throw Error('请等待本轮新牌全部咪出并公开');if(handoff)throw Error('请先完成或取消庄家交接');if(mode==='solo'){if(action==='start')startRound();else if(action==='next')openBettingInternal();else if(action==='dealerStep'&&game.phase==='dealer'){game.dealerStep();accountSettlement();}else if(!executeHand(action,id,'solo',amount))throw Error('请在自己的当前手牌操作，并确认可用筹码');emit(action==='next'?(tableSession()?.notice||'已开启下注，所有玩家须重新确认。'):'');runAI();return true;}if(mode!=='online'||!online())throw Error('请等待房间连接恢复');if(role==='host'){if(action==='dealerStep'&&game.phase==='dealer'){game.dealerStep();accountSettlement();}else if(action==='start'){if(!readyPlayers())throw Error('等待玩家在线：'+(offlineWarning()||'席位同步尚未完成'));startRound();}else if(action==='next')openBettingInternal();else throw Error('当前操作不属于你的回合');rev++;await broadcast();emit(action==='next'?(tableSession()?.notice||'已开启下注，所有玩家须重新确认。'):'');return true;}if(['insure','evenMoney'].includes(action)){const p=rawGame().players.find(p=>physical(p)===id);if(rawGame().phase!=='insurance'||!owns(id)||!p?.insurancePending)throw Error('该席位没有待选保险');if(action==='insure'&&(typeof amount!=='number'||amount<0||!Number.isInteger(amount*2)||amount>(p.baseBet||p.bet)/2||amount>balance(myPeer())-committed(myPeer())))throw Error('保险额度无效或可用筹码不足');if(action==='evenMoney'&&!p.natural)throw Error('只有天然21可选平赔');}else{const p=currentHand(id);if(!['hit','stand','double','surrender','split'].includes(action)||!p||!owns(physical(p))||activeHand()!==id||rawGame().phase!=='player')throw Error('请在自己的当前手牌操作');if((action==='double'||action==='split')&&balance(myPeer())-committed(myPeer())<(p.baseBet||p.bet))throw Error('可用筹码不足');}return guestAction(action,id,amount);}
  async function sessionAction(action,id,amount){if(handoff||mode==='online'&&(!online()||pendingAction))throw Error('请等待连接和操作确认');if(mode==='online'&&role!=='host')return guestAction(action,id,amount);if(mode!=='solo'&&role!=='host')throw Error('请先进入房间');if(!bettingAction(action,mode==='solo'?'solo':myPeer(),id,amount))throw Error('当前阶段或本人权限不允许此操作');if(role==='host'){rev++;await broadcast();}emit('');return true;}

  function runAI(){cancel(aiTimer);if(mode!=='solo'||game.phase!=='dealer'||revealPending())return;aiTimer=later(()=>{if(mode!=='solo'||game.phase!=='dealer')return;game.dealerStep();accountSettlement();emit('熊二按规则完成庄家行动。');runAI();},650);}
  async function guard(fn){try{return await fn();}catch(e){emit(e.message||'操作暂未完成，请重试。');return false;}}
