   setName:value=>guard(async()=>{const next=validName(value);if(!next)throw Error('昵称请填写1–16个字符，不使用尖括号');name=next;write('daydream.nickname',name);if(pendingInvite&&mode==='entry'){const target=pendingInvite;await enter(target.room,target.join,target.alias);}else{if(mode==='online')hello().catch(()=>{});else if(mode==='solo')for(const id of IDS)if(seats[id])seats[id].name=name;emit('');}return true;}),
   solo:()=>guard(async()=>{if(!name)throw Error('请先填写昵称');cleanup();mode='solo';role='solo';owner=null;pendingInvite=null;code='';alias='';members=[];game=new T.Engine({chips:true,classic:true,infinite:true});soloMeta=emptyMeta();seats=emptySeats();claim('s1','solo',null,name);emit('可认领更多空位，一人最多同时玩四手。');return true;}),
   createRoom:()=>guard(async()=>{if(!name)throw Error('请先填写昵称');cleanup();owner={...emptyMeta(),...await C.identity()};code=owner.code;game=new T.Engine({chips:true,classic:true,infinite:true});owner.saved=game.snapshot();owner.expires=wall()+86400000;owner.rev=0;owner.seats=emptySeats();if(!write(ownerKey(),owner))throw Error('浏览器无法保存房间，请允许本地存储后重试');await openRoom(code,'host');return true;}),
